let gDrums = [];

const gBackground = 255;
const gColorPalettes = [
  {
    name: 'highschool',
    colors: ['#FF2400', '#CC1D00', '#991600', '#4FC3FF', '#3A9CCE', '#2B769E', '#FFFFFF'],
  },
  {
