    name: 'portland', // didn't know that portland had a flag!
    colors: ['#006A4E', '#0072CE', '#FFD100', '#FFFFFF'],
  },
];

function setup() {
  createCanvas(windowWidth, windowHeight);
  frameRate(60);
  init();
  background(gBackground);
  noStroke();
}

function draw() {
  // === Variant 3: Fractal Orbit Matrix ===
  gridOffset = noise(frameCount * 0.01) * 80;
  push();
  translate(gridOffset, -gridOffset);

  background(gBackground);
  for (let drum of gDrums) {
    drum.draw();
  }

  pop();
}

function init() {
  const columnCount = floor(random(15, 30));
  const boxWidth = width / columnCount;
  const baseSizeScalar = random(0.3, 0.5);
  const baseSize = boxWidth * baseSizeScalar; // base diameter
  const rowCount = floor(height / boxWidth);

  gDrums = [];
  const selectedPalette = random(gColorPalettes);

  const activeColumns = columnCount - 2; // skip edges
  const activeRows = rowCount - 1;

  const gridWidth = activeColumns * boxWidth;
  const gridHeight = activeRows * boxWidth;

  const xOffset = (width - gridWidth) / 2;
  const yOffset = (height - gridHeight) / 2;

  let normDrum;

  const oddsItsUnique = random(0.05, 0.1);

  for (let col = 0; col < activeColumns; col++) {
    const x = xOffset + (0.5 + col) * boxWidth;

    for (let row = 0; row < activeRows; row++) {
      const y = yOffset + (0.5 + row) * boxWidth;
      const randCol = random(selectedPalette.colors);
      let drum;

      let isUnique = gDrums.length <= 0 || random() < oddsItsUnique;

      if (!isUnique) {
        drum = normDrum.clone();
        drum.pos = createVector(x, y);
        drum.fill = randCol;
      } else {
        const bpm = gDrums.length <= 0 ? random(20,40) : random(15,60);

        const pulseScaleMax = 0.9;//1; //constrain(random(baseSizeScalar * 1.01, 1), 0, 1);

        const maxPulseDiameter = boxWidth * pulseScaleMax;
        const maxPulseSize = maxPulseDiameter - baseSize;

        const phaseOffset = random();

        drum = new Drum({
          xp: x,
          yp: y,
          bpm: bpm,
          baseSize: baseSize,
          pulseSize: maxPulseSize,
          phaseOffset: phaseOffset,
          color: randCol,
          elapsed: random(0, 60000 / bpm),
        });
      }

      if (gDrums.length <= 0) {
        normDrum = drum;
      }

      gDrums.push(drum);
    }
  }

  gDrums = shuffle(gDrums);
}

function mouseClicked() {
  init();
}

class Drum {
  constructor(data) {
    this._initData = { ...data };
    this.pos = createVector(data.xp, data.yp);
    this.bpm = data.bpm;
    this.baseSize = data.baseSize;
    this.pulseSize = data.pulseSize;
    this.phaseOffset = data.phaseOffset || 0;

    this.curSize = this.baseSize;
    this.beatLength = 60000 / this.bpm;
    this.elapsed = data.elapsed;

    this.fill = data.color;
  }

  update() {
    this.elapsed += deltaTime;

    const phase = (this.elapsed / this.beatLength + this.phaseOffset) % 1;
    const eased = (1 - cos(TWO_PI * phase)) / 2;
    this.curSize = this.baseSize + this.pulseSize * eased;
  }

  draw() {
    this.update();
    fill(this.fill);
    circle(this.pos.x, this.pos.y, this.curSize);
  }

  clone() {
    return new Drum({ ...this._initData });
  }
}


